         assertEquals(400, get("/reports/revenue?month=july").statusCode());
         assertEquals(400, get("/reports/occupancy").statusCode());
     }
+
+    @Test
+    void childrenIsOptionalAndDefaultsToZero() throws Exception {
+        HttpResponse<String> created = post("/reservations", RESERVATION_JSON);
+        JsonNode reservation = json.readTree(created.body());
+
+        assertEquals(201, created.statusCode());
+        assertEquals(0, reservation.get("children").asInt());
+    }
+
+    @Test
+    void reservationsWithChildrenShowTheFieldInTheResponse() throws Exception {
+        String withChildren = """
+                {"roomNumber": 301, "guestName": "Maria Silva", "guestEmail": "maria@example.com",
+                 "guestCpf": "222.333.444-55", "checkIn": "2027-07-10", "checkOut": "2027-07-12",
+                 "guests": 2, "children": 2, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> created = post("/reservations", withChildren);
+        JsonNode reservation = json.readTree(created.body());
+
+        assertEquals(201, created.statusCode());
+        assertEquals(2, reservation.get("children").asInt());
+    }
+
+    @Test
+    void adultsAndChildrenTogetherCannotExceedCapacity() throws Exception {
+        String tooMany = """
+                {"roomNumber": 101, "guestName": "Pedro Costa", "guestEmail": "pedro@example.com",
+                 "guestCpf": "333.444.555-66", "checkIn": "2027-07-10", "checkOut": "2027-07-12",
+                 "guests": 1, "children": 2, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> response = post("/reservations", tooMany);
+
+        assertEquals(422, response.statusCode());
+        assertEquals("CAPACITY_EXCEEDED", json.readTree(response.body()).get("error").asText());
+    }
 }
